import{_ as t,o as a,c as r,ak as n}from"./chunks/framework.B8jO0odJ.js";const h=JSON.parse('{"title":"Chainy player flow","description":"Owner: Sherwin (experience), Christian (behavior), Miguel (screens). October 12, 2026.","frontmatter":{"title":"Chainy player flow","description":"Owner: Sherwin (experience), Christian (behavior), Miguel (screens). October 12, 2026.","source":"docs/design/app-flow.md","category":"Game & system design","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/design/app-flow.md","filePath":"content/docs/design/app-flow.md"}'),s={name:"content/docs/design/app-flow.md"};function o(i,e,d,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[n(`<div><h1 id="chainy-player-flow">Chainy player flow<a class="header-anchor" href="#chainy-player-flow" aria-label="Link to this section">​</a></h1><p>Owner: Sherwin (experience), Christian (behavior), Miguel (screens). October 12, 2026.</p><figure class="diagram"><div class="mermaid-source"><pre>flowchart TD
  A[Open game] --&gt; B[Create or select local profile]
  B --&gt; C[Load saved progress]
  C --&gt; D[Enter learning level]
  D --&gt; E[Read or hear lesson / dialogue]
  E --&gt; F[Start Quiz, Wordle or BlockMatch]
  F --&gt; G[Show feedback and result]
  G --&gt; H[Save progress]
  H --&gt;|Success| I[Continue, retry or leave]
  H --&gt;|Failure| J[Explain save error]
  J --&gt; H
  I --&gt; D
  I --&gt; B
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><p>“Retry” after an activity result is different from retrying a failed save. An activity replay may count as a new attempt under the agreed rule; retrying the same save must not.</p><h2 id="states-and-recovery">States and recovery<a class="header-anchor" href="#states-and-recovery" aria-label="Link to this section">​</a></h2><table><thead><tr><th>State</th><th>Allowed next action</th><th>What prevents a wrong result</th></tr></thead><tbody><tr><td>Startup</td><td>Open data and required services → profile screen</td><td>Show a recovery message on database/version failure; preserve existing data</td></tr><tr><td>Profile</td><td>Validate input → create/select → load records</td><td>Confirm a new profile; no gameplay until the read succeeds</td></tr><tr><td>Level loading</td><td>Load scene/content → ready</td><td>Disable play during loading; failure returns to a usable screen</td></tr><tr><td>Exploration/dialogue</td><td>Move, interact, start an available mode</td><td>Do not start two modes from repeated taps</td></tr><tr><td>Quiz</td><td>Submit an answer → feedback → next/end</td><td>One accepted response per submission; scoring follows the frozen rules</td></tr><tr><td>Wordle</td><td>Enter a guess → validate → letter feedback → continue/end</td><td>Invalid input is handled consistently; duplicate letters and guess limits follow the rules</td></tr><tr><td>BlockMatch</td><td>Move → evaluate → animate/cascade → ready/end</td><td>Ignore moves until resolution finishes; bounded cascade/no-move recovery</td></tr><tr><td>Result/save</td><td>Request save → success or failure</td><td>Do not claim saved completion early; retry the same result without double counting</td></tr><tr><td>Pause</td><td>Resume, leave or switch profile</td><td>Freeze gameplay input; resolve pending save before discarding session state</td></tr><tr><td>Return/switch</td><td>Stop active mode → clear old learner state → load chosen profile</td><td>No stale scores, events or UI from the previous learner</td></tr><tr><td>Relaunch</td><td>Load last supported saved point</td><td>No promise of exact mid-animation resume; explain any restarted activity</td></tr></tbody></table><p>These are acceptance rules. The exact internal state names belong to Christian&#39;s implementation.</p><h2 id="questions-to-close-on-existing-tasks">Questions to close on existing tasks<a class="header-anchor" href="#questions-to-close-on-existing-tasks" aria-label="Link to this section">​</a></h2><ul><li>CH-02: pass/finish rules, Wordle limits and dictionary, BlockMatch no-move and cascade limits.</li><li>CH-04: repeated-save handling, checkpoint boundary, progress/attempt meanings.</li><li>CH-05/26: back/pause controls, scene-load failure, leaving with an unsaved result.</li><li>CH-11: teacher export, cancellation and collection confirmation.</li></ul><p>Miguel&#39;s handoff is a screen flow plus a walk-through of these error cases. Christian checks behavior; Sherwin checks whether a beginner can understand the next action. No additional release-review framework is required.</p></div>`,1)])])}const g=t(s,[["render",o]]);export{h as __pageData,g as default};
